use std::{env,fs,path::Path};
use wasmc::lib_tool_rust_consumer_sdk::native_build::NativePinnedFile;
use wasmc::lib_tool_rust_consumer_sdk::native_build::host::{compile_host_canonical_source,HostContract,HostContractPair};
fn sha(b:&[u8])->String{wasmc::self_bundle::hex(&wasmc::self_bundle::sha256(b))}
fn contract(dir:&Path,selection:&[&str])->HostContract{let f=|n|fs::read(dir.join(n)).unwrap();let(wit,execution_abi,provider_contract,binding)=(f("lib.wit"),f("execution-abi.json"),f("provider-contract.json"),f("binding.json"));HostContract{schema:"wasmc.canonical-host-contract/v1".into(),wit_sha256:sha(&wit),execution_abi_sha256:sha(&execution_abi),provider_contract_sha256:sha(&provider_contract),binding_sha256:sha(&binding),wit,execution_abi,provider_contract,binding,selected_operations:vec![],operation_selection:Some(selection.iter().map(|x|x.to_string()).collect())}}
fn main(){let a:Vec<_>=env::args().collect();let base=Path::new(&a[1]);let f=base.join("examples/current/string-support-v2");let kit=base.join("current-libs/wasmc-text/0.0.2");let root=kit;let hostroot=f.join("host");let host=HostContractPair{entry:contract(&hostroot.join("entry"),&[]),operations:contract(&hostroot.join("operations"),&[])};let source=fs::read_to_string(f.join("source.wasmc")).unwrap();let pin=sha(&fs::read(root.join("lib.json")).unwrap());let app=compile_host_canonical_source(&source,&root,&pin,&host,17).expect("native compilation");let template=wasmc::lib_tool_rust_consumer_sdk::native_build::host::generate_canonical_lib_template(&root,&pin).expect("template");fs::write(base.join("selected-string-template.json"),template).unwrap();fs::write(base.join("selected-string-transfer.rs"),app.transfer_source).unwrap();println!("selected_root_source_prepared=true");}
